begin;
set local standard_conforming_strings = on;
select pg_advisory_xact_lock(73421, 1);
do $seed$ declare v_group uuid; v_script uuid; v_versions jsonb; begin
select id into v_group from public.admin_script_groups where name = 'Activation Experience' order by created_at limit 1;
if v_group is null then insert into public.admin_script_groups(name) values ('Activation Experience') returning id into v_group; end if;
v_versions := '[{"label": "Jordan original", "sections": [{"id": "opening", "title": "Opening and choice", "content": "A life without a life vision is directionless. That’s why we start with life vision - so we know where we’re going and what to align with.\n\nRemember, conscious creation is saying, out of the infinite buffet of options, this is what I choose to include in my life experience. The life vision is your CHOICE of what to include.\n\nOnce that decision is made, we activate it through audio and visualization so we can align our thoughts, words and actions with it UNTIL we experience it in our physical reality.\n\nBasically, we’re impressing our subconscious mind with what we choose to experience until our conscious mind can catch up and find the evidence in our physical reality of us already living it now!", "locked": false}, {"id": "vibrational-grammar", "title": "Vibrational Grammar", "content": "The magic of the life vision is in vibrational grammar. Over the last 15 years, we have discovered how to write our dream reality in a way that the Universal can deliver what we choose. Most people write from the lack of what they want… “It would be nice if…” “When I’m in my dream job…” “The hard times are over…” etc. Although it sounds well meaning, the opposite of what they want to experience is being activated!", "locked": false}, {"id": "meet-viva", "title": "Meet VIVA", "content": "That’s why we created VIVA: our Vibrationally Intelligent Virtual Assistant. She knows vibrational grammar as well as the Universe. She writes only in present tense, activating what is wanted, with vivid emotion so the senses can connect with the subconscious mind and make things feel real now (which then allows them to be attracted into our physical reality).\n\nEven if you don’t know what you want, VIVA is trained to extract clarity from all of your contrast, creating a beautiful comprehensive life vision that’s in harmony across all 12 life categories. Nothing contradicts anything. Everything in present tense. With immersive feeling words. To take you from your current reality to the one you’ve chosen.", "locked": false}, {"id": "invitation", "title": "Your invitation to begin", "content": "Talk with VIVA life your closest friend. Share your deepest fears and your biggest desires. She will beautifully translate it all into the Life You Choose. Have fun with this! VIVA is your bridge to your ultimate reality. Now it’s time to peek into what’s on the other side of that bridge.", "locked": false}], "source": "personal"}, {"label": "Business draft — post-purchase welcome", "sections": [{"id": "opening", "title": "Opening and choice", "content": "### Begin With Your Life Vision\n\nWelcome to Vibration Fit.\n\nYou’re about to create the foundation for your Conscious Creation System: your **Life Vision**.\n\nYour Life Vision is a clear picture of the life you choose to experience across the areas that matter most to you.\n\nNot what you think you’re supposed to want.\n\nNot what feels realistic based on your current circumstances.\n\nWhat you genuinely choose.", "locked": false}, {"id": "meet-viva", "title": "Meet VIVA", "content": "You’ll begin by sharing your desires, frustrations, questions, and dreams with VIVA, your Vibrationally Intelligent Virtual Assistant.\n\nYou don’t need to have perfect clarity before you begin. VIVA will help you find the patterns inside what you share and translate them into a comprehensive vision for your life.\n\nYour vision will be written in present tense, with vivid language and emotion, so it feels real, personal, and connected to the experience you’re choosing now.\n\nThink of this as selecting what you want included in your life from the infinite possibilities available to you.\n\nOnce your Life Vision is complete, you’ll activate it through audio, visualization, and daily alignment.\n\nThe goal is simple:\n\nTo bring your thoughts, words, and actions into harmony with the life you’ve chosen.", "locked": false}, {"id": "invitation", "title": "Your invitation to begin", "content": "Take your time. Be honest. Be specific. Have fun with it.\n\nTalk to VIVA like you’re talking to your closest friend. Share the desires you’re proud of, the dreams you’ve kept private, and even the parts of your life you’re ready to change.\n\nYou don’t have to know exactly where this is going.\n\nYou only have to begin.\n\n**When you’re ready, tap below to start your conversation with VIVA.**", "locked": false}], "source": "personal"}, {"label": "Personal rewrite — preserve the mechanism", "sections": [{"id": "opening", "title": "Opening and choice", "content": "## Start With What You Choose\n\nA life without a Life Vision is directionless.\n\nThat’s why everything inside Vibration Fit starts here.\n\n**Your Life Vision is your choice.**\n\nConscious creation is looking at the infinite buffet of possibilities and saying:\n\n**This. This is what I choose to include in my life experience.**\n\nOnce you make that choice, you have something to align with.\n\nYou’ll activate your Life Vision through audio and visualization, then practice aligning your thoughts, words, and actions with it—until what you’ve chosen becomes what you’re experiencing.\n\nIn other words, you’re repeatedly impressing your subconscious mind with the reality you choose, while training your conscious mind to notice, expect, and participate in that reality now.", "locked": false}, {"id": "vibrational-grammar", "title": "Vibrational Grammar", "content": "### The Magic Is in the Language\n\nOver the last 15 years, we’ve learned that **how you write your vision matters.**\n\nMost people unknowingly write from the absence of what they want:\n\n*“It would be nice if…”*\n\n*“When I finally have my dream job…”*\n\n*“The hard times are over…”*\n\nEven though the intention is positive, the language keeps attention connected to the reality they’re trying to move beyond.\n\nWe call the alternative **Vibrational Grammar**.\n\nYour Life Vision is written in the present tense, focused entirely on what you choose to experience, with vivid feeling and sensory language that helps your chosen reality feel real **now**.\n\nAnd you don''t have to know how to write that way.\n\nThat’s what VIVA is for.", "locked": false}, {"id": "meet-viva", "title": "Meet VIVA", "content": "### Meet VIVA\n\nVIVA is your **Vibrationally Intelligent Virtual Assistant**.\n\nYou bring her the raw material—your dreams, desires, frustrations, fears, contrast, half-formed ideas, and the things you haven''t quite figured out how to put into words.\n\n**She helps you turn all of it into clarity.**\n\nEven if you don''t know exactly what you want yet, VIVA can help you discover it through conversation and translate it into a beautiful, comprehensive Life Vision across all 12 areas of your life.\n\nEverything works together.\n\nEverything points toward what you choose.\n\nEverything is written as the life you''re living now.", "locked": false}, {"id": "invitation", "title": "Your invitation to begin", "content": "So don''t try to say the “right” thing.\n\n**Talk to VIVA like you would your closest friend.**\n\nTell her what''s working. Tell her what''s not. Share the dreams that excite you and the desires you''ve barely admitted to yourself.\n\nHave fun with it.\n\nVIVA is the bridge between the reality you''re experiencing and the reality you''re choosing.\n\n**Now let''s peek at what''s waiting on the other side.**", "locked": false}], "source": "personal"}, {"label": "Business draft — shared free and paid introduction", "sections": [{"id": "opening", "title": "Opening and choice", "content": "### Start With Your Life Vision\n\nYou’re about to create the foundation for your Conscious Creation System: your **Life Vision**.\n\nA life without a clear vision is directionless. You may be busy, working hard, and making decisions every day, but without knowing what you’re choosing, your life is largely shaped by default.\n\nYour Life Vision changes that.\n\nIt is your conscious choice of what you want to include in your life experience: the relationships, work, health, environment, experiences, emotions, and abundance that matter most to you.\n\nYou are not here to write what you think you should want.\n\nYou are here to give yourself permission to choose.", "locked": false}, {"id": "meet-viva", "title": "Meet VIVA", "content": "You’ll begin by talking with VIVA, your Vibrationally Intelligent Virtual Assistant.\n\nYou can share your biggest desires, your deepest fears, the areas of life that feel out of alignment, and the dreams you may not have said out loud yet.\n\nYou do not need to arrive with perfect clarity. VIVA will help you uncover what is already inside you and organize it into a comprehensive Life Vision across 12 areas of your life.\n\nYour vision is written in present tense, with vivid language and emotion, so your mind and senses can connect with the reality you are choosing.\n\nOnce your Life Vision is created, you can activate it through audio, visualization, and daily alignment.\n\nThe purpose is to bring your thoughts, words, and actions into harmony with the life you have chosen, until that vision becomes something you recognize in your physical reality.", "locked": false}, {"id": "invitation", "title": "Your invitation to begin", "content": "Think of this as the first step across the bridge between your current reality and your chosen reality.\n\nTalk to VIVA like your closest friend. Be honest. Be specific. Include the things you want, the things you are ready to release, and the experiences you are ready to welcome.\n\nThere are no wrong answers.\n\nYou only need to begin.\n\n**Tap below and start creating your Life Vision now.**", "locked": false}], "source": "personal"}, {"label": "Personal rewrite — Free Activation and member video", "sections": [{"id": "opening", "title": "Opening and choice", "content": "Before you start creating your Life Vision, we want you to understand why this is the first step.\n\nBecause a life without a vision is directionless.\n\nYou can work hard, make decisions, set goals, and stay incredibly busy—but if you haven''t consciously decided what you''re creating, it''s really easy to keep creating by default.\n\n**Your Life Vision is that decision.**\n\nThink about conscious creation like standing in front of an infinite buffet of possibilities and saying:\n\n**“This. This is what I choose to include in my life experience.”**\n\nThat''s your Life Vision.\n\nAnd once you''ve made that choice, now you have something to align with.\n\nWe activate your vision through audio and visualization so you can begin aligning your thoughts, your words, and your actions with the reality you''ve chosen.\n\nYou''re essentially impressing your subconscious mind with what you choose to experience, while training your conscious mind to recognize more and more evidence of that reality around you.", "locked": false}, {"id": "vibrational-grammar", "title": "Vibrational Grammar", "content": "And here''s where something really important comes in.\n\n**How you write your Life Vision matters.**\n\nOver the last 15 years, we''ve developed what we call **Vibrational Grammar**.\n\nBecause most of us unknowingly talk about what we want from the lack of it.\n\n“It would be nice if…”\n\n“When I finally have my dream job…”\n\n“The hard times are over…”\n\nIt sounds positive—but your attention is still connected to what isn''t here, what hasn''t happened, or what you don''t want.\n\nVibrational Grammar flips that.\n\nWe write your Life Vision entirely from the reality you **choose**.\n\nPresent tense.\n\nFocused on what you want.\n\nFilled with emotion, sensory detail, and language that allows you to begin experiencing that reality **now**.\n\nAnd here''s the best part:\n\n**You don''t have to know how to do any of that.**", "locked": false}, {"id": "meet-viva", "title": "Meet VIVA", "content": "That''s why we created VIVA—your Vibrationally Intelligent Virtual Assistant.\n\nYou just talk.\n\nTell her what''s happening in your life right now. Tell her what you love. What you don''t love. What you''re afraid of. What you wish were different. What you secretly dream about.\n\nAnd if you have no idea what you want?\n\n**That''s okay too.**\n\nVIVA is trained to help you turn contrast into clarity.\n\nShe''ll take everything you share and help you uncover what you actually choose, then translate it into a Life Vision written in Vibrational Grammar.", "locked": false}, {"id": "invitation", "title": "Your invitation to begin", "content": "So don''t try to give VIVA the perfect answer.\n\n**Talk to her like your closest friend.**\n\nBe raw. Dream big. Change your mind. Explore.\n\nThis is your life.\n\nYou get to choose what goes in it.\n\nAnd VIVA is here to help you put that choice into words.\n\n**So have fun with this.**\n\nYou''re about to peek across the bridge from the reality you''re living now…\n\n**into the Life You Choose.**", "locked": false}], "source": "personal"}]'::jsonb;
v_script := public.import_admin_script_v2('a247fcbf-b9bc-5eb6-bad8-6b24779ba6c6'::uuid, null, 'Before You Create Your Life Vision', v_versions, v_group);
if (select count(*) from public.admin_script_versions where script_id = v_script) <> 5 then raise exception 'Unexpected version count'; end if;
if exists (select 1 from jsonb_array_elements(v_versions) with ordinality p(value, n) left join public.admin_script_versions v on v.script_id = v_script and v.version_number = p.n where v.id is null or v.content is distinct from (select string_agg(s.value->>'content', E'\n\n' order by s.n) from jsonb_array_elements(p.value->'sections') with ordinality s(value,n)) or v.sections is distinct from p.value->'sections') then raise exception 'Seed verification failed'; end if;
v_versions := '[{"label": "Business draft — membership invitation", "sections": [{"id": "opening", "title": "Opening and whole-life vision", "content": "### Your Life Vision Is Just the Beginning\n\nYou’ve now created a Life Vision for one area of your life.\n\nThat gives you clarity around what you choose to experience.\n\nBut imagine having that same level of clarity across **all 12 areas of your life**, with every part working together instead of competing for your attention.\n\nThat is what becomes possible inside the full Vibration Fit membership.\n\nThe process is simple:", "locked": false}, {"id": "choose", "title": "Choose", "content": "First, you get clear on the life you choose with VIVA.", "locked": false}, {"id": "activate", "title": "Activate", "content": "Then, you activate that vision through audio, visualization, and daily tools that help you stay connected to it.", "locked": false}, {"id": "align", "title": "Align and work through wobbles", "content": "As you activate, old thought patterns and beliefs may surface. That is normal. They are simply patterns that may not support the life you are choosing now.\n\nInside VIVA chat, you can talk through whatever is happening in your life, especially when you feel uncertain, distracted, or out of alignment.\n\nVIVA helps you identify the patterns creating those wobbles and guides you back toward beliefs and actions that support your Life Vision.", "locked": false}, {"id": "tools", "title": "Personal tools and Manifestations", "content": "Over time, those conversations become personalized data that helps shape the tools you need most.", "locked": false}, {"id": "membership", "title": "Membership and community", "content": "Inside the membership, you’ll receive:\n\n- A comprehensive Life Vision across all 12 life categories\n- Weekly live group coaching inside the Alignment Gym\n- The Vibe Tribe community for support, connection, and shared momentum\n- Manifestations that turn your vision into an interactive visual experience\n- Immersive Stories created from your journal entries, visions, and desires\n- Personalized Incantations to reinforce the beliefs you choose\n- SparkQuery prompts that direct your attention toward new possibilities\n- Ongoing VIVA support whenever life changes or you feel yourself wobble\n\nYou do not have to figure everything out alone.\n\nYou have a system that helps you clarify what you want, activate it, recognize what is competing with it, and return to alignment again and again.\n\nThe Free Activation helps you begin.\n\nThe Vibration Fit membership gives you the complete system to keep going.", "locked": false}, {"id": "closing", "title": "Closing invitation", "content": "If you’re ready to create the Life You Choose across every area of your life, join us inside Vibration Fit.\n\n**Tap below to become a member and continue your activation.**", "locked": false}], "source": "personal"}, {"label": "Personal rewrite — Conscious Creation cycle", "sections": [{"id": "opening", "title": "Opening and whole-life vision", "content": "## Now Imagine Your Whole Life\n\nYou just did something really powerful.\n\nYou consciously chose what you want to experience in one area of your life.\n\n**Now imagine doing this across your entire life.**\n\nYour health. Your relationships. Your family. Your work. Your money. Your home. Your experiences. Your growth.\n\nAll 12 areas of your life, intentionally designed to work together as one comprehensive vision for the **Life You Choose**.\n\nThat''s where Vibration Fit begins.\n\nBecause creating your Life Vision isn''t something you do once and then put away.\n\n**It''s the beginning of a cycle.**", "locked": false}, {"id": "choose", "title": "Choose", "content": "First, you **choose**.\n\nYou work with VIVA to get clear on the life you want to experience and put that choice into words.", "locked": false}, {"id": "activate", "title": "Activate", "content": "Then, you **activate** it.\n\nYour Life Vision becomes personalized audio, visual experiences, and vibrational tools that help you repeatedly connect with that reality until it becomes increasingly familiar.", "locked": false}, {"id": "align", "title": "Align and work through wobbles", "content": "And then something really important happens.\n\n**Life happens.**\n\nYou have a conversation.\n\nSomething doesn''t go the way you expected.\n\nAn old fear comes up.\n\nYou notice yourself thinking the same thought you''ve thought for years.\n\nA belief surfaces that directly competes with the reality you''ve chosen.\n\nWe call those moments **wobbles**.\n\nAnd they''re not interruptions to the process.\n\n**They''re part of the process.**\n\nBecause now you can see what has been running underneath the surface.\n\nInstead of letting that wobble pull you back into creating by default, you bring it to VIVA.\n\nTalk to her about what''s happening just like you would a coach who already knows the life you''ve chosen.\n\nVIVA helps you uncover the thought patterns and beliefs underneath the wobble, identify what we call your **Vibrational Constraints**, and alchemize them into beliefs that support where you''re going.", "locked": false}, {"id": "tools", "title": "Personal tools and Manifestations", "content": "And the more you use Vibration Fit, the more personal the system becomes.\n\nYour conversations.\n\nYour journal entries.\n\nYour manifestations.\n\nYour wobbles.\n\nYour breakthroughs.\n\nYour evolving Life Vision.\n\nThey become information the system can use to help you create personalized tools for your alignment.\n\nVIVA can turn what you''re working through into an Incantation.\n\nShe can create a SparkQuery that gives your subconscious something new to look for.\n\nShe can help you create an immersive Story that lets you experience a piece of your vision from the inside.\n\nYour Manifestations give you a visual connection to what you''re creating.\n\nAnd your Life Vision brings it all back to the life you''ve consciously chosen.", "locked": false}, {"id": "evolution", "title": "Clarity and vision versions", "content": "But there''s another part of this that we think is incredibly important.\n\n**Your Life Vision is allowed to change.**\n\nBecause as you activate and align with what you''ve chosen, you start noticing more.\n\nYou discover what feels amazing.\n\nYou experience things you thought you wanted and realize you want something different.\n\nYou uncover desires you couldn''t even see from your previous perspective.\n\nYou get clearer.\n\nAnd with that new clarity, you get to **choose again**.\n\nSo you return to your Life Vision.\n\nYou refine it.\n\nYou expand it.\n\nYou create a new version.\n\nAnd we keep your previous versions, so you can look back and actually see how your vision—and your life—have evolved.\n\n**That''s conscious creation.**\n\nYou choose.\n\nYou activate.\n\nYou live.\n\nYou notice.\n\nYou realign.\n\nYou evolve.\n\n**And then you choose again.**\n\nIt''s not a finish line.\n\nIt''s a way of living.", "locked": false}, {"id": "membership", "title": "Membership and community", "content": "And you don''t have to do it alone.\n\nEvery week, we come together live inside the **Alignment Gym** to work through what''s surfacing, celebrate what''s unfolding, and practice alignment together.\n\nAnd inside the **Vibe Tribe**, you''re surrounded by other people who are consciously choosing their lives too.\n\nWhat you just experienced in your Free Activation is one piece of what''s possible.\n\nInside Vibration Fit, you can build your Life Vision across **all 12 areas of your life** and have the tools, coaching, community, and VIVA beside you as you activate it, align with it, experience it, and continue choosing what comes next.", "locked": false}, {"id": "closing", "title": "Closing invitation", "content": "Because there will always be more clarity.\n\nMore expansion.\n\nMore life to experience.\n\n**You can never get it done.**\n\nAnd that''s the fun of it.\n\nWelcome to the Conscious Creation System.\n\n**The Life You Choose starts here.**", "locked": false}], "source": "personal"}, {"label": "Personal rewrite — correct categories and system", "sections": [{"id": "opening", "title": "Opening and whole-life vision", "content": "# Now Imagine Your Whole Life\n\nYou just did something really powerful.\n\nYou consciously chose what you want to experience in one area of your life.\n\n**Now imagine doing this across your entire life.**\n\nFun. Health. Travel. Love. Family. Social. Home. Work. Money. Stuff. Giving. Spirituality.\n\nAll 12 areas of your life, intentionally designed to work together as one comprehensive vision for the **Life You Choose**.\n\nThat''s where Vibration Fit begins.\n\nBecause creating your Life Vision isn''t something you do once and then put away.\n\nIt''s part of an ongoing practice we call the **Conscious Creation System.**\n\nAnd the system is simple:\n\n**Choose. Activate. Align.**", "locked": false}, {"id": "choose", "title": "Choose", "content": "First, you **CHOOSE**.\n\nYou work with VIVA to get clear on the life you choose to experience and put that choice into words across all 12 areas of your life.", "locked": false}, {"id": "activate", "title": "Activate", "content": "Then, you **ACTIVATE** it.\n\nYour Life Vision becomes personalized audio, visual experiences, and vibrational tools that help you repeatedly connect with that reality until it becomes increasingly familiar.", "locked": false}, {"id": "align", "title": "Align and work through wobbles", "content": "And then you **ALIGN**.\n\nBecause while you''re choosing and activating...\n\n**life is still happening.**\n\nYou have a conversation.\n\nSomething doesn''t go the way you expected.\n\nAn old fear comes up.\n\nYou notice yourself thinking the same thought you''ve thought for years.\n\nA belief surfaces that directly competes with the reality you''ve chosen.\n\nWe call those moments **wobbles**.\n\nAnd they''re not interruptions to the process.\n\n**They''re part of living it.**\n\nBecause now you can see what has been running underneath the surface.\n\nInstead of letting that wobble pull you back into creating by default, you bring it to VIVA.\n\nTalk to her about what''s happening just like you would a coach who already knows the life you''ve chosen.\n\nVIVA helps you uncover the thought patterns and beliefs underneath the wobble, identify what we call your **Vibrational Constraints**, and alchemize them into beliefs that support the life you''ve chosen.", "locked": false}, {"id": "tools", "title": "Personal tools and Manifestations", "content": "And the more you use Vibration Fit, the more personal the system becomes.\n\nYour conversations.\n\nYour journal entries.\n\nYour manifestations.\n\nYour wobbles.\n\nYour breakthroughs.\n\nYour evolving Life Vision.\n\nThey become information the system can use to understand you more deeply, track your progress over time, and help create personalized tools for your alignment.\n\nVIVA can turn what you''re working through into an **Incantation**.\n\nShe can create a **SparkQuery** that gives your subconscious something new to look for.\n\nShe can help you create an immersive **Story** that lets you experience a piece of your chosen reality from the inside.\n\nAnd your **Manifestations** become living containers for the things you''re consciously creating—why you want them, how you choose for them to feel, the inspired actions that come to you, and the journey as they unfold into your physical reality.\n\nAnd yes, you get to see them too.\n\nBecause every Manifestation can have a visual representation that helps you activate what you''re creating.\n\nEverything brings you back to the life you''ve consciously chosen.", "locked": false}, {"id": "evolution", "title": "Clarity and vision versions", "content": "But there''s another part of this that we think is incredibly important.\n\n**Your Life Vision is allowed to change.**\n\nBecause life never stops while you''re using the Conscious Creation System.\n\nYou''re living.\n\nYou''re experiencing.\n\nYou''re discovering what feels amazing and what doesn''t.\n\nYou experience things you thought you wanted and realize you want something different.\n\nYou uncover desires you couldn''t even see from your previous perspective.\n\nYou get clearer.\n\nAnd all of that new clarity gives you an opportunity to **CHOOSE again.**\n\nSo you return to your Life Vision.\n\nYou refine it.\n\nYou expand it.\n\nYou create a new version.\n\nAnd we keep your previous versions, so you can look back and actually see how your vision—and your life—have evolved.\n\nThat''s why the Conscious Creation System isn''t six steps or seven steps.\n\nIt doesn''t change depending on what''s happening in your life.\n\nIt''s always:\n\n**CHOOSE.**\n\n**ACTIVATE.**\n\n**ALIGN.**\n\nAnd all the while...\n\n**you live.**\n\nLife gives you more experiences.\n\nMore contrast.\n\nMore desires.\n\nMore clarity.\n\nAnd you bring that new clarity right back into the system.\n\n**Choose. Activate. Align.**\n\nAgain and again, as you live and evolve.\n\nIt''s not a finish line.\n\n**It''s a way of living.**", "locked": false}, {"id": "membership", "title": "Membership and community", "content": "And you don''t have to do it alone.\n\nEvery week, we come together live inside the **Alignment Gym** to work through what''s surfacing, celebrate what''s unfolding, and practice alignment together.\n\nAnd inside the **Vibe Tribe**, you''re surrounded by other people who are consciously choosing their lives too.\n\nWhat you just experienced in your Free Activation is one piece of what''s possible.\n\nInside Vibration Fit, you build your Life Vision across **all 12 areas of your life** and have VIVA, your personalized tools, live coaching, and a community beside you as you continually **Choose, Activate, and Align** with the Life You Choose.", "locked": false}, {"id": "closing", "title": "Closing invitation", "content": "Because there will always be more clarity.\n\nMore expansion.\n\nMore life to experience.\n\n**You can never get it done.**\n\nAnd that''s the fun of it.\n\nWelcome to the **Conscious Creation System.**\n\n**The Life You Choose starts here.**", "locked": false}], "source": "personal"}, {"label": "Business draft — tightened invitation", "sections": [{"id": "opening", "title": "Opening and whole-life vision", "content": "### Now Imagine Your Whole Life\n\nYou just did something powerful.\n\nYou consciously chose what you want to experience in one area of your life.\n\nNow imagine doing that across your entire life.\n\nYour fun. Health. Travel. Love. Family. Social life. Home. Work. Money. Possessions. Giving. Spirituality.\n\nAll 12 areas, intentionally designed to support the Life You Choose.\n\nThat is where Vibration Fit begins.\n\nBecause your Life Vision is not something you create once and put away.\n\nIt is part of an ongoing process we call the **Conscious Creation System**.\n\nThe process is simple:\n\n**Choose. Activate. Align.**", "locked": false}, {"id": "choose", "title": "Choose", "content": "First, you **choose**.\n\nYou work with VIVA to clarify the life you want and express it across all 12 areas of your life.", "locked": false}, {"id": "activate", "title": "Activate", "content": "Then, you **activate**.\n\nYour vision becomes personalized audio, visual experiences, and vibrational tools that help you reconnect with what you are creating.", "locked": false}, {"id": "align", "title": "Align and work through wobbles", "content": "Then, you **align**.\n\nBecause life continues to happen.\n\nA conversation brings up an old fear.\n\nSomething does not go as planned.\n\nYou notice yourself repeating a familiar thought.\n\nWe call these moments **wobbles**.\n\nA wobble is not a failure. It is information.\n\nBring it to VIVA.\n\nTalk through what happened, what you felt, and what you want to experience instead. VIVA helps you identify the beliefs and patterns competing with your chosen reality, then guides you back toward thoughts and actions that support your vision.\n\nOver time, your conversations, journal entries, manifestations, wobbles, breakthroughs, and evolving Life Visions make the system increasingly personal.", "locked": false}, {"id": "tools", "title": "Personal tools and Manifestations", "content": "VIVA can transform what you are working through into:\n\n- Incantations\n- SparkQuery prompts\n- Immersive Stories\n- Personalized Manifestations\n- New Life Vision updates", "locked": false}, {"id": "evolution", "title": "Clarity and vision versions", "content": "And your Life Vision is allowed to change.\n\nAs you live, experience, and learn more about yourself, your desires become clearer.\n\nYou may discover what truly feels aligned, what no longer belongs, and what you want to choose next.\n\nSo you return to your Life Vision.\n\nYou refine it.\n\nYou expand it.\n\nYou create a new version.\n\nEvery version is saved, so you can revisit your journey and see how your vision, identity, and life have evolved.\n\nThat is the Conscious Creation System:\n\n**Choose. Activate. Align.**\n\nAgain and again.", "locked": false}, {"id": "membership", "title": "Membership and community", "content": "Inside Vibration Fit, you do not have to do this alone.\n\nYou receive the complete Life Vision experience across all 12 areas, personalized tools, weekly live coaching inside the Alignment Gym, and the Vibe Tribe community.\n\nThe Free Activation gives you one piece of the process.\n\nMembership gives you the system to keep practicing, evolving, and returning to alignment.\n\nYou can never get it done.\n\nAnd that is the fun of it.\n\n**Join Vibration Fit and continue creating the Life You Choose.**", "locked": false}], "source": "personal"}, {"label": "Personal rewrite — Choose, Activate, Align", "sections": [{"id": "opening", "title": "Opening and whole-life vision", "content": "# Now Imagine Your Whole Life\n\nYou just did something powerful.\n\nYou consciously chose what you want to experience in one area of your life.\n\n**Now imagine doing this across your entire life.**\n\nYour Fun. Health. Travel. Love. Family. Social life. Home. Work. Money. Stuff. Giving. Spirituality.\n\nAll 12 areas, intentionally designed to work together as one comprehensive vision for the **Life You Choose**.\n\nThat''s where Vibration Fit begins.\n\nBecause your Life Vision isn''t something you create once and put away.\n\nIt''s part of an ongoing practice we call the **Conscious Creation System.**\n\nAnd the system is simple:\n\n**CHOOSE. ACTIVATE. ALIGN.**", "locked": false}, {"id": "choose", "title": "Choose", "content": "First, you **CHOOSE**.\n\nYou work with VIVA to get clear on the life you choose to experience and put that choice into words across all 12 areas of your life.", "locked": false}, {"id": "activate", "title": "Activate", "content": "Then, you **ACTIVATE**.\n\nYour Life Vision becomes personalized audio, visual experiences, and vibrational tools that help you connect with your chosen reality and make it increasingly familiar.", "locked": false}, {"id": "align", "title": "Align and work through wobbles", "content": "Then, you **ALIGN**.\n\nBecause while you''re choosing and activating...\n\n**life is still happening.**\n\nA conversation brings up an old fear.\n\nSomething doesn''t go the way you expected.\n\nYou notice yourself repeating a thought you''ve thought for years.\n\nA belief surfaces that competes with the reality you''ve chosen.\n\nWe call those moments **wobbles**.\n\nAnd a wobble isn''t a failure.\n\n**It''s information.**\n\nBring it to VIVA.\n\nTalk to her about what happened, how you''re feeling, and what you want to experience instead.\n\nVIVA helps you uncover the thought patterns and beliefs underneath the wobble, identify what we call your **Vibrational Constraints**, and alchemize them into beliefs that support the life you''ve chosen.", "locked": false}, {"id": "tools", "title": "Personal tools and Manifestations", "content": "And the more you use Vibration Fit, the more personal the system becomes.\n\nYour conversations. Your journal entries. Your manifestations. Your wobbles. Your breakthroughs. Your evolving Life Vision.\n\nAll of it helps VIVA understand you more deeply, track your progress over time, and create personalized tools to support your alignment.\n\nShe can create **Incantations**, **SparkQueries**, and immersive **Stories** from what you''re experiencing.\n\nAnd **Manifestations** become living containers for the things you''re consciously creating—why you want them, how you choose for them to feel, the inspired actions that come to you, and the journey as they unfold into your physical reality.", "locked": false}, {"id": "evolution", "title": "Clarity and vision versions", "content": "But here''s one of our favorite parts:\n\n**Your Life Vision is allowed to change.**\n\nBecause while you''re using this system...\n\n**you''re living.**\n\nYou''re having experiences.\n\nYou''re discovering what feels amazing and what doesn''t.\n\nYou''re getting clearer about what you want and what you don''t want.\n\nNew desires emerge that you couldn''t even see from where you were before.\n\nAnd all of that new clarity gives you an opportunity to **CHOOSE again.**\n\nYou return to your Life Vision.\n\nYou refine it.\n\nYou expand it.\n\nYou create a new version.\n\nAnd every version is saved, so you can look back and actually see how your vision—and your life—have evolved.\n\nThat''s the Conscious Creation System.\n\n**CHOOSE. ACTIVATE. ALIGN.**\n\nAgain and again...\n\n**while you live.**\n\nLife keeps giving you more experiences, more contrast, more desires, and more clarity.\n\nAnd you keep consciously choosing what comes next.\n\nIt''s not a finish line.\n\n**It''s a way of living.**", "locked": false}, {"id": "membership", "title": "Membership and community", "content": "And you don''t have to do it alone.\n\nEvery week, we come together live inside the **Alignment Gym** to work through what''s surfacing, celebrate what''s unfolding, and practice alignment together.\n\nAnd inside the **Vibe Tribe**, you''re surrounded by other people who are consciously choosing their lives too.\n\nWhat you just experienced in your Free Activation is one piece of what''s possible.\n\nInside Vibration Fit, you build your Life Vision across **all 12 areas of your life** and have VIVA, your personalized vibrational tools, weekly live coaching, and a community beside you as you continually:\n\n**CHOOSE.**\n\n**ACTIVATE.**\n\n**ALIGN.**", "locked": false}, {"id": "closing", "title": "Closing invitation", "content": "Because there will always be more clarity.\n\nMore expansion.\n\nMore life to experience.\n\n**You can never get it done.**\n\nAnd that''s the fun of it.\n\n**Join Vibration Fit and keep creating the Life You Choose.**", "locked": false}], "source": "personal"}, {"label": "Business draft — final polish", "sections": [{"id": "opening", "title": "Opening and whole-life vision", "content": "### Now Imagine Your Whole Life\n\nYou just did something powerful.\n\nYou consciously chose what you want to experience in one area of your life.\n\nNow imagine doing that across your entire life.\n\nYour fun, health, travel, love, family, social life, home, work, money, possessions, giving, and spirituality.\n\nAll 12 areas, intentionally designed to work together as one comprehensive vision for the Life You Choose.\n\nThat is where Vibration Fit begins.\n\nYour Life Vision is not something you create once and put away. It is part of an ongoing practice we call the **Conscious Creation System**.\n\nAnd the system is simple:\n\n**Choose. Activate. Align.**", "locked": false}, {"id": "choose", "title": "Choose", "content": "First, you **choose**.\n\nYou work with VIVA to clarify the life you choose to experience and put that choice into words across all 12 areas of your life.", "locked": false}, {"id": "activate", "title": "Activate", "content": "Then, you **activate**.\n\nYour Life Vision becomes personalized audio, visual experiences, and vibrational tools that help you connect with your chosen reality and make it increasingly familiar.", "locked": false}, {"id": "align", "title": "Align and work through wobbles", "content": "Then, you **align**.\n\nBecause while you are choosing and activating, life is still happening.\n\nA conversation brings up an old fear.\n\nSomething does not go as expected.\n\nYou notice yourself repeating a familiar thought.\n\nA belief surfaces that competes with the life you have chosen.\n\nWe call these moments **wobbles**.\n\nA wobble is not a failure.\n\nIt is information.\n\nBring it to VIVA. Talk about what happened, how you feel, and what you want to experience instead.\n\nVIVA helps you uncover the patterns underneath the wobble, identify your Vibrational Constraints, and create beliefs and tools that support the life you have chosen.", "locked": false}, {"id": "tools", "title": "Personal tools and Manifestations", "content": "She can turn what you are experiencing into Incantations, SparkQueries, immersive Stories, and personalized Manifestations.\n\nThe more you use Vibration Fit, the more personal the system becomes.\n\nYour conversations, journal entries, manifestations, wobbles, breakthroughs, and evolving Life Vision all help you build a clearer record of your journey.", "locked": false}, {"id": "evolution", "title": "Clarity and vision versions", "content": "And your Life Vision is allowed to change.\n\nBecause while you are using the system, you are living.\n\nYou are discovering what feels aligned, what no longer belongs, and what you want next.\n\nSo you return to your Life Vision.\n\nYou refine it.\n\nYou expand it.\n\nYou create a new version.\n\nEvery version is saved, so you can look back and see how your vision and your life have evolved.\n\nThat is the Conscious Creation System:\n\n**Choose. Activate. Align.**\n\nAgain and again, while you live.", "locked": false}, {"id": "membership", "title": "Membership and community", "content": "Inside Vibration Fit, you do not have to do this alone. You receive the complete Life Vision experience across all 12 areas, personalized tools, weekly live coaching inside the Alignment Gym, and the Vibe Tribe community.\n\nThe Free Activation is one piece of what is possible.\n\nMembership gives you the complete system to keep creating, practicing, and evolving. Ongoing value is what makes continuity compelling. [$100M Money Models, Page 147],[$100M Playbook Retention, Page 20]", "locked": false}, {"id": "closing", "title": "Closing invitation", "content": "There will always be more clarity, more expansion, and more life to experience.\n\nYou can never get it done.\n\nAnd that is the fun of it.\n\n**Join Vibration Fit and keep creating the Life You Choose.**", "locked": false}], "source": "personal"}, {"label": "Personal rewrite — restored Manifestations and membership", "sections": [{"id": "opening", "title": "Opening and whole-life vision", "content": "# Now Imagine Your Whole Life\n\nYou just did something powerful.\n\nYou consciously chose what you want to experience in one area of your life.\n\n**Now imagine doing that across your entire life.**\n\nYour Fun. Health. Travel. Love. Family. Social life. Home. Work. Money. Stuff. Giving. Spirituality.\n\nAll 12 areas, intentionally designed to work together as one comprehensive vision for the **Life You Choose**.\n\nThat is where Vibration Fit begins.\n\nYour Life Vision isn''t something you create once and put away. It''s part of an ongoing practice we call the **Conscious Creation System**.\n\nAnd the system is simple:\n\n**CHOOSE. ACTIVATE. ALIGN.**", "locked": false}, {"id": "choose", "title": "Choose", "content": "First, you **CHOOSE**.\n\nYou work with VIVA to clarify the life you choose to experience and put that choice into words across all 12 areas of your life.", "locked": false}, {"id": "activate", "title": "Activate", "content": "Then, you **ACTIVATE**.\n\nYour Life Vision becomes personalized audio, visual experiences, and vibrational tools that help you connect with your chosen reality and make it increasingly familiar.", "locked": false}, {"id": "align", "title": "Align and work through wobbles", "content": "Then, you **ALIGN**.\n\nBecause while you''re choosing and activating...\n\n**life is still happening.**\n\nA conversation brings up an old fear.\n\nSomething doesn''t go as expected.\n\nYou notice yourself repeating a familiar thought.\n\nA belief surfaces that competes with the life you''ve chosen.\n\nWe call these moments **wobbles**.\n\nA wobble isn''t a failure.\n\n**It''s information.**\n\nBring it to VIVA.\n\nTalk about what happened, how you feel, and what you want to experience instead.\n\nVIVA helps you uncover the patterns underneath the wobble, identify your **Vibrational Constraints**, and create beliefs and tools that support the life you''ve chosen.", "locked": false}, {"id": "tools", "title": "Personal tools and Manifestations", "content": "She can turn what you''re experiencing into **Incantations**, **SparkQueries**, and immersive **Stories**.\n\nAnd your **Manifestations** become living containers for what you''re consciously creating—why you want it, how you choose for it to feel, the inspired actions that come to you, and the journey as it unfolds into your physical reality.\n\nThe more you use Vibration Fit, the more personal the system becomes.\n\nYour conversations, journal entries, Manifestations, wobbles, breakthroughs, and evolving Life Vision create a living record of your journey and help VIVA support you more personally over time.", "locked": false}, {"id": "evolution", "title": "Clarity and vision versions", "content": "And your Life Vision is allowed to change.\n\nBecause while you''re using the system...\n\n**you''re living.**\n\nYou''re discovering what feels aligned, what no longer belongs, and what you want next.\n\nThat new clarity comes right back into **CHOOSE**.\n\nYou refine your Life Vision.\n\nYou expand it.\n\nYou create a new version.\n\nAnd every version is saved, so you can look back and see how your vision—and your life—have evolved.\n\nThat''s the Conscious Creation System:\n\n**CHOOSE. ACTIVATE. ALIGN.**\n\nAgain and again...\n\n**while you live.**", "locked": false}, {"id": "membership", "title": "Membership and community", "content": "And inside Vibration Fit, you don''t have to do it alone.\n\nYou get the complete Life Vision experience across all 12 areas of your life, personalized vibrational tools, weekly live coaching inside the **Alignment Gym**, and the **Vibe Tribe** community.\n\nWhat you just experienced in your Free Activation is one piece of what''s possible.\n\n**Membership gives you the complete system for consciously creating across your whole life.**", "locked": false}, {"id": "closing", "title": "Closing invitation", "content": "There will always be more clarity.\n\nMore expansion.\n\nMore life to experience.\n\n**You can never get it done.**\n\nAnd that''s the fun of it.\n\n**Join Vibration Fit and keep creating the Life You Choose.**", "locked": false}], "source": "personal"}, {"label": "Final — comprehensive and congruent, membership line preserved", "sections": [{"id": "opening", "title": "Opening and whole-life vision", "content": "# Now Imagine Your Whole Life\n\nYou just did something powerful.\n\nYou consciously chose what you want to experience in one area of your life.\n\n**Now imagine doing that across your entire life.**\n\nYour Fun. Health. Travel. Love. Family. Social life. Home. Work. Money. Stuff. Giving. Spirituality.\n\nNot 12 separate visions competing with each other.\n\n**One comprehensive, congruent vision for your whole life.**\n\nVIVA helps you bring all 12 areas into harmony—so the life you choose in one area supports the life you choose everywhere else.\n\nYour success at Work doesn''t have to come at the expense of your Family.\n\nMore Money doesn''t have to mean less Fun.\n\nYour Health doesn''t have to wait until everything else is handled.\n\n**Because you really can have it all.**\n\nThat''s where Vibration Fit begins.\n\nYour Life Vision isn''t something you create once and put away. It''s part of an ongoing practice we call the **Conscious Creation System**.\n\nAnd the system is simple:\n\n**CHOOSE. ACTIVATE. ALIGN.**", "locked": false}, {"id": "choose", "title": "Choose", "content": "First, you **CHOOSE**.\n\nYou work with VIVA to clarify the life you choose to experience and put that choice into words across all 12 areas of your life.", "locked": false}, {"id": "activate", "title": "Activate", "content": "Then, you **ACTIVATE**.\n\nYour Life Vision becomes personalized audio, visual experiences, and vibrational tools that help you connect with your chosen reality and make it increasingly familiar.", "locked": false}, {"id": "align", "title": "Align and work through wobbles", "content": "Then, you **ALIGN**.\n\nBecause while you''re choosing and activating...\n\n**life is still happening.**\n\nA conversation brings up an old fear.\n\nSomething doesn''t go as expected.\n\nYou notice yourself repeating a familiar thought.\n\nA belief surfaces that competes with the life you''ve chosen.\n\nWe call these moments **wobbles**.\n\nA wobble isn''t a failure.\n\n**It''s information.**\n\nBring it to VIVA.\n\nTalk about what happened, how you feel, and what you want to experience instead.\n\nVIVA helps you uncover the patterns underneath the wobble, identify your **Vibrational Constraints**, and create beliefs and tools that support the life you''ve chosen.", "locked": false}, {"id": "tools", "title": "Personal tools and Manifestations", "content": "She can turn what you''re experiencing into **Incantations**, **SparkQueries**, and immersive **Stories**.\n\nAnd your **Manifestations** become living containers for what you''re consciously creating—why you want it, how you choose for it to feel, the inspired actions that come to you, and the journey as it unfolds into your physical reality.\n\nThe more you use Vibration Fit, the more personal the system becomes.\n\nYour conversations, journal entries, Manifestations, wobbles, breakthroughs, and evolving Life Vision create a living record of your journey and help VIVA support you more personally over time.", "locked": false}, {"id": "evolution", "title": "Clarity and vision versions", "content": "And your Life Vision is allowed to change.\n\nBecause while you''re using the system...\n\n**you''re living.**\n\nYou''re discovering what feels aligned, what no longer belongs, and what you want next.\n\nThat new clarity comes right back into **CHOOSE**.\n\nYou refine your Life Vision.\n\nYou expand it.\n\nYou create a new version.\n\nAnd every version is saved, so you can look back and see how your vision—and your life—have evolved.\n\nThat''s the Conscious Creation System:\n\n**CHOOSE. ACTIVATE. ALIGN.**\n\nAgain and again...\n\n**while you live.**", "locked": false}, {"id": "membership", "title": "Membership and community", "content": "And inside Vibration Fit, you don''t have to do it alone.\n\nYou get the complete Life Vision experience across all 12 areas of your life, personalized vibrational tools, weekly live coaching inside the **Alignment Gym**, and the **Vibe Tribe** community.\n\nWhat you just experienced in your Free Activation is one piece of what''s possible.\n\n**Membership gives you the complete system for consciously creating across your whole life.**", "locked": false}, {"id": "closing", "title": "Closing invitation", "content": "There will always be more clarity.\n\nMore expansion.\n\nMore life to experience.\n\n**You can never get it done.**\n\nAnd that''s the fun of it.\n\n**Join Vibration Fit and keep creating the Life You Choose.**", "locked": false}], "source": "personal"}]'::jsonb;
v_script := public.import_admin_script_v2('bb7e3da3-1404-5192-b7ba-98baeeb0677e'::uuid, null, 'Now Imagine Your Whole Life', v_versions, v_group);
if (select count(*) from public.admin_script_versions where script_id = v_script) <> 8 then raise exception 'Unexpected version count'; end if;
if exists (select 1 from jsonb_array_elements(v_versions) with ordinality p(value, n) left join public.admin_script_versions v on v.script_id = v_script and v.version_number = p.n where v.id is null or v.content is distinct from (select string_agg(s.value->>'content', E'\n\n' order by s.n) from jsonb_array_elements(p.value->'sections') with ordinality s(value,n)) or v.sections is distinct from p.value->'sections') then raise exception 'Seed verification failed'; end if;
end $seed$;
commit;
select s.id, s.title, g.name as group_name, s.sort_order, count(v.id) as versions from public.admin_scripts s join public.admin_script_groups g on g.id = s.group_id join public.admin_script_versions v on v.script_id = s.id where g.name = 'Activation Experience' group by s.id, g.name order by s.sort_order;